WORKSPACE_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>AgentWhite Target Workspace</title>
<style>
:root{--bg:#07100d;--panel:#0d1915;--panel2:#11231d;--line:#1e3a30;--text:#d9f8e8;--muted:#83a795;--green:#5dffa7;--amber:#ffcc66;--red:#ff6b6b;--blue:#79c9ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace}.shell{max-width:1300px;margin:auto;padding:22px}.top,.row,.actions,.tabs{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:14px}.brand{font-size:24px;font-weight:800;letter-spacing:1px}.brand span{color:var(--green)}.btn,button{border:1px solid #2d624c;background:#10291f;color:var(--text);padding:8px 11px;border-radius:8px;cursor:pointer;text-decoration:none}.btn:hover,button:hover{border-color:var(--green);color:var(--green)}button.primary{color:var(--green);border-color:#347d58}button.danger{color:#ffaaaa;border-color:#6c3838;background:#281414}.grid{display:grid;grid-template-columns:.75fr 1.6fr;gap:14px}@media(max-width:900px){.grid{grid-template-columns:1fr}}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden}.head{padding:12px 14px;border-bottom:1px solid var(--line)}.body{padding:11px}.card{border:1px solid var(--line);background:var(--panel2);border-radius:9px;padding:10px;margin-bottom:8px}.title{font-weight:700}.muted{color:var(--muted)}.badge{font-size:10px;padding:3px 6px;border:1px solid var(--line);border-radius:999px;text-transform:uppercase}.badge.ok{color:var(--green);border-color:#347d58}.badge.warn{color:var(--amber)}.badge.bad{color:var(--red)}.right{margin-left:auto}.tabs{margin-bottom:10px}.tabs button.active{color:var(--green);border-color:var(--green)}pre{white-space:pre-wrap;word-break:break-word;background:#050b08;border:1px solid #172a22;padding:8px;border-radius:7px;color:#abd5c0;max-height:220px;overflow:auto}.empty{padding:20px;text-align:center;color:var(--muted)}.action{border-left:3px solid var(--blue)}.access{border-left:3px solid var(--green)}.history{border-left:3px solid var(--muted)}.finding{border-left:3px solid var(--amber)}.crumb{color:var(--green);font-size:12px;margin-top:3px}.toast{position:fixed;right:16px;bottom:16px;background:#10291f;border:1px solid #347d58;padding:10px;border-radius:8px;display:none;max-width:420px}.toast.error{background:#2a1515;border-color:#844}
</style>
</head>
<body>
<div class="shell">
  <div class="top"><div><div class="brand">AGENT<span>WHITE</span> · TARGET WORKSPACE</div><div class="muted">Every test is explicit. Results and access points stay saved while you navigate.</div></div><a class="btn" href="/">Back to Dashboard</a></div>
  <div class="grid">
    <div class="panel"><div class="head"><strong>ENROLLED TARGETS</strong></div><div id="targets" class="body"><div class="empty">Loading…</div></div></div>
    <div class="panel"><div class="head"><strong id="workspace-title">WORKSPACE</strong><div id="crumb" class="crumb">Select an enrolled target</div></div><div id="workspace" class="body"><div class="empty">Select a target to open its saved engagement.</div></div></div>
  </div>
</div>
<div id="toast" class="toast"></div>
<script>
let state={devices:[]};let ws=null;let tab='tests';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function toast(msg,error=false){const e=document.getElementById('toast');e.textContent=msg;e.className='toast'+(error?' error':'');e.style.display='block';setTimeout(()=>e.style.display='none',3500)}
async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d}
async function loadTargets(){try{state=await api('/api/state');const rows=(state.devices||[]).filter(d=>d.enrolled);const el=document.getElementById('targets');el.innerHTML=rows.length?rows.map(d=>`<div class="card"><div class="row"><div><div class="title">${esc(d.name)}</div><div class="muted">${esc(d.kind)} · ${esc(d.address||'')}</div></div><span class="right badge ok">ENROLLED</span></div><div class="actions" style="margin-top:8px"><button class="primary" onclick="openWorkspace('${esc(d.id)}')">Open Workspace</button></div></div>`).join(''):'<div class="empty">No enrolled targets yet. Enroll one from the main dashboard.</div>'}catch(e){toast(e.message,true)}}
async function openWorkspace(id){try{ws=await api('/api/workspace?device_id='+encodeURIComponent(id));tab='tests';renderWorkspace()}catch(e){toast(e.message,true)}}
function setTab(t){tab=t;renderWorkspace()}
function renderWorkspace(){if(!ws)return;const d=ws.device;document.getElementById('workspace-title').textContent=d.name||d.id;document.getElementById('crumb').textContent=(d.name||d.id)+' › engagement › '+tab;const tabs=['overview','tests','access','history','findings'];document.getElementById('workspace').innerHTML=`<div class="tabs">${tabs.map(t=>`<button class="${tab===t?'active':''}" onclick="setTab('${t}')">${t.toUpperCase()}</button>`).join('')}<button class="danger right" onclick="clearWorkspace()">Clear Saved Workspace</button></div>${renderTab()}`}
function renderTab(){if(tab==='overview')return overview();if(tab==='tests')return tests();if(tab==='access')return access();if(tab==='history')return history();return findings()}
function overview(){const e=ws.engagement||{};return `<div class="card"><div class="title">Engagement state</div><div class="muted">Status: ${esc(e.status||'saved')}<br>Started: ${esc(e.started_at||'')}<br>Updated: ${esc(e.updated_at||'')}</div></div><div class="card"><div class="row"><span>Saved tests</span><span class="right badge">${(ws.action_runs||[]).length}</span></div><div class="row"><span>Saved access points</span><span class="right badge">${(ws.access_sessions||[]).length}</span></div><div class="row"><span>Findings</span><span class="right badge">${(ws.findings||[]).length}</span></div></div>`}
function tests(){const rows=ws.available_actions||[];if(!rows.length)return '<div class="empty">No actions available while this target is outside active scope.</div>';return rows.map(a=>`<div class="card action"><div class="row"><div><div class="title">${esc(a.label)}</div><div class="muted">${esc(a.description)}</div></div><span class="right badge ${a.effect==='PASSIVE'?'ok':'warn'}">${esc(a.effect)}</span></div><div class="actions" style="margin-top:8px">${a.kind==='access'?`<button class="primary" onclick="openSavedAccess(${Number(a.parameters?.port||0)})">Open Saved Access</button>`:`<button class="primary" onclick="runAction('${esc(a.id)}')">Run This Test</button>`}</div></div>`).join('')}
async function runAction(actionId){toast('Running only the selected test…');try{const r=await api('/api/action',{method:'POST',body:JSON.stringify({device_id:ws.device.id,action_id:actionId})});ws=r.workspace;renderWorkspace();toast(r.result?.summary||'Test complete. Waiting for your next selection.')}catch(e){toast(e.message,true);await openWorkspace(ws.device.id)}}
function access(){const rows=ws.access_sessions||[];if(!rows.length)return '<div class="empty">No saved access points yet.</div>';return rows.map(s=>`<div class="card access"><div class="row"><div><div class="title">${esc(s.label)}</div><div class="muted">Last seen: ${esc(s.last_seen_at)}</div></div><span class="right badge ${s.status==='ready'?'ok':'warn'}">${esc(s.status)}</span></div><pre>${esc(JSON.stringify(s.endpoint||{},null,2))}</pre><div class="actions">${s.kind==='http'?`<button class="primary" onclick="openSavedAccess(${Number((s.endpoint||{}).port||0)})">Return to Access</button>`:''}${s.kind==='bluetooth'?`<button class="primary" onclick="runAction('bluetooth.gatt.inspect')">Reconnect & Inspect</button>`:''}<button onclick="setTab('history')">View Test History</button><button onclick="setTab('findings')">View Fix Guidance</button></div></div>`).join('')}
function history(){const rows=ws.action_runs||[];if(!rows.length)return '<div class="empty">No tests have been run yet.</div>';return rows.map(r=>`<div class="card history"><div class="row"><div><div class="title">${esc(r.label)}</div><div class="muted">${esc(r.started_at)}${r.completed_at?' → '+esc(r.completed_at):''}</div></div><span class="right badge ${r.status==='success'?'ok':r.status==='failed'?'bad':'warn'}">${esc(r.status)}</span></div><div class="muted">Elapsed: ${r.elapsed_ms??'—'} ms · ${esc(r.action_id)}</div><pre>${esc(JSON.stringify(r.result||{},null,2))}</pre></div>`).join('')}
function findings(){const rows=ws.findings||[];if(!rows.length)return '<div class="empty">No findings recorded yet.</div>';return rows.map(f=>`<div class="card finding"><div class="row"><div class="title">${esc(f.title)}</div><span class="right badge">${esc(f.severity)}</span></div><div class="muted">${esc(f.created_at)} · ${esc(f.status)}</div><pre>${esc(JSON.stringify(f.proof||{},null,2))}</pre><div><strong>How to fix:</strong> ${esc(f.remediation)}</div></div>`).join('')}
function openSavedAccess(port){window.location.href='/?workspace_device='+encodeURIComponent(ws.device.id)+'&port='+encodeURIComponent(port)}
async function clearWorkspace(){if(!confirm('Clear saved tests, access points, and findings for this target?'))return;try{const r=await api('/api/workspace/clear',{method:'POST',body:JSON.stringify({device_id:ws.device.id})});ws=r.workspace;renderWorkspace();toast('Saved workspace cleared; enrollment remains.')}catch(e){toast(e.message,true)}}
loadTargets();
</script>
</body>
</html>'''
